import type { EvidenceStatus, MetricDefinition, ProjectKind } from "@/lib/miror-design-system";

export type HomeId="hero"|"company"|"capabilities"|"work"|"process"|"quality"|"legacy"|"contact";
export type ProjectState="published"|"review"|"hidden";
