export interface CapabilityItem{id:string;title:string;summary:string;discipline:string;signal:string;}
export interface ProcessStep{id:string;phase:string;title:string;body:string;checks:string[];}
export interface HomeSection{id:HomeId;index:string;label:string;heading:string;subheading:string;tone:"paper"|"dark"|"sand";}

