export function publishedProjects(){return projects.filter((p)=>p.state==="published"&&p.publicationPermission);}
export function projectBySlug(slug:string){return projects.find((p)=>p.slug===slug&&p.state==="published"&&p.publicationPermission);}
export function relatedProjects(project:V4Project,limit=3){return projects.filter((p)=>p.slug!==project.slug&&p.state==="published").sort((a,b)=>Number(b.featured)-Number(a.featured)).slice(0,limit);}
export function projectCount(){return projects.length;}
export function pendingCount(){return pendingProjectSlots.length;}

